struct hook { int (*fn)(struct event *e, void *ctx); void *ctx; struct hook *next; };
static struct hook *chain;

void hook_register(struct hook *h) { h->next = chain; chain = h; }

int dispatch(struct event *e)
{
    for (struct hook *h = chain; h; h = h->next)
        if (h->fn(e, h->ctx) != 0)
            return -1;                 /* veto: stop the chain */
    return 0;
}
